import{_ as l,r as a,o as c,c as r,e as t,a as n,s as e}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"过滤器范围 - October CMS - 3.x","titleTemplate":false,"description":"了解如何使用范围过滤列表。","frontmatter":{"subtitle":"了解如何使用范围过滤列表。"},"headers":[{"level":2,"title":"可用范围","slug":"可用范围","link":"#可用范围","children":[]},{"level":2,"title":"范围属性","slug":"范围属性","link":"#范围属性","children":[{"level":3,"title":"应用模型范围","slug":"应用模型范围","link":"#应用模型范围","children":[]},{"level":3,"title":"范围依赖","slug":"范围依赖","link":"#范围依赖","children":[]}]}],"relativePath":"3.x/zh-cn/element/filter-scopes.md","filePath":"3.x/zh-cn/element/filter-scopes.md"}'),i={name:"3.x/zh-cn/element/filter-scopes.md"};function u(d,s,k,g,y,h){const p=a("pre-heading"),o=a("post-heading");return c(),r("div",null,[t(p),s[0]||(s[0]=n("h1",null,"过滤器范围",-1)),t(o),s[1]||(s[1]=e(`<p>过滤器范围是过滤器使用的范围定义，通常与列表结合使用。与列表列类似，它们在以下区域中使用：</p><ul><li><a href="./../extend/lists/list-controller.html">后端列表控制器</a></li><li><a href="./../extend/forms/relation-controller.html">后端关联控制器</a></li></ul><p>所有过滤器范围都通过各自的 <strong>type</strong> 属性来标识。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">scopes</span><span class="token punctuation">:</span>
    <span class="token key atrule">myscope</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> date
        <span class="token comment"># ...</span>
</code></pre></div><h2 id="可用范围"><a href="#可用范围" class="header-anchor">#</a> 可用范围</h2><p>以下过滤器范围可用：</p>`,6)),s[2]||(s[2]=n("div",{class:"content-list-p",markdown:"1"},[n("p",null,[n("a",{href:"./filter/scope-checkbox.html"},"Checkbox"),n("a",{href:"./filter/scope-switch.html"},"Switch"),n("a",{href:"./filter/scope-text.html"},"Text"),n("a",{href:"./filter/scope-number.html"},"Number"),n("a",{href:"./filter/scope-dropdown.html"},"Dropdown"),n("a",{href:"./filter/scope-group.html"},"Group"),n("a",{href:"./filter/scope-date.html"},"Date")])],-1)),s[3]||(s[3]=e(`<h2 id="范围属性"><a href="#范围属性" class="header-anchor">#</a> 范围属性</h2><p>对于每个范围，您可以指定以下属性（如适用）。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>向用户显示过滤器范围时使用的名称。</td></tr><tr><td><strong>type</strong></td><td>定义此范围的显示方式。默认值：<code>group</code>。</td></tr><tr><td><strong>conditions</strong></td><td>启用或禁用条件函数，或指定要应用于每个条件的原始 where 查询语句，详情请参阅范围类型定义。</td></tr><tr><td><strong>modelClass</strong></td><td>用作数据源和本地方法调用引用的模型类。</td></tr><tr><td><strong>modelScope</strong></td><td>指定在<strong>列表模型</strong>上定义的<a href="./../extend/database/model.html">模型查询范围</a>方法，应用于列表查询。第一个参数将包含查询对象（与常规范围方法相同），第二个参数将包含范围定义，包括其填充的值。</td></tr><tr><td><strong>options</strong></td><td>按多个项目过滤时使用的选项，以数组形式提供。</td></tr><tr><td><strong>optionsMethod</strong></td><td>从模型上定义的方法名或作为静态方法调用请求选项，例如 <code>Class::method</code>。</td></tr><tr><td><strong>emptyOption</strong></td><td>用于有意空选择的可选标签。</td></tr><tr><td><strong>default</strong></td><td>为过滤器提供默认值，可以是数组、字符串或整数，具体取决于过滤器值。</td></tr><tr><td><strong>permissions</strong></td><td>当前后端用户必须拥有的<a href="./../extend/backend/permissions.html">权限</a>才能使用过滤器范围。支持单个权限的字符串或权限数组（只需其中一个即可授予访问权限）。</td></tr><tr><td><strong>dependsOn</strong></td><td>此范围依赖的其他范围名称的字符串或数组。当其他范围被修改时，此范围将重置。</td></tr><tr><td><strong>nameFrom</strong></td><td>用于显示过滤器标签的模型属性名称。默认值：<code>name</code>。</td></tr><tr><td><strong>valueFrom</strong></td><td>定义用于源值的模型属性。默认值来自范围名称。</td></tr><tr><td><strong>order</strong></td><td>确定显示顺序时的数值权重，默认值每个范围递增 100 点。</td></tr><tr><td><strong>after</strong></td><td>使用显示顺序（+1）将此范围放置在另一个现有范围名称之后。</td></tr><tr><td><strong>before</strong></td><td>使用显示顺序（-1）将此范围放置在另一个现有范围名称之前。</td></tr></tbody></table></div><h3 id="应用模型范围"><a href="#应用模型范围" class="header-anchor">#</a> 应用模型范围</h3><p>大多数过滤器将使用合理的默认值应用其范围约束。<code>modelScope</code> 属性可用于使用<a href="./../extend/database/model.html">模型范围方法定义</a>将自定义约束应用于过滤器查询。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfilter</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> My Filter
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> applyMyFilter
</code></pre></div><p>在上面的示例中，我们期望在主模型上有一个名为 <strong>myfilter</strong> 的关联，并且在关联模型上定义了一个名为 <strong>scopeApplyMyFilter</strong> 的方法。第二个参数将包含范围定义，包括其填充的值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeApplyMyFilter</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_filter_attribute&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>modelScope</code> 属性也可以定义为静态 PHP 类方法（<code>Class::method</code>）。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfilter</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> My Filter
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> <span class="token string">&quot;App\\MyCustomClass::applyMyFilter&quot;</span>
</code></pre></div><p>在此示例中，该方法应在指定的类名上声明为静态方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">App</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">MyCustomClass</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">function</span> <span class="token function-definition function">applyMyFilter</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_filter_attribute&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="范围依赖"><a href="#范围依赖" class="header-anchor">#</a> 范围依赖</h3><p><code>dependsOn</code> 属性允许您将多个过滤器链接在一起。当依赖项被修改时，过滤器范围将重置以允许新的条件。以下是两个范围定义的示例。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">country</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group

<span class="token key atrule">state</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> State
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
    <span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> getCityOptionsForFilter
</code></pre></div><p>state 范围依赖于 country 范围的值，选项在 PHP 中使用 <strong>getCityOptionsForFilter</strong> 方法进行过滤。此方法的第一个参数将包含整组范围定义，包括它们的当前值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCityOptionsForFilter</span><span class="token punctuation">(</span><span class="token variable">$scopes</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$scopes</span><span class="token operator">-&gt;</span><span class="token property">country</span> <span class="token operator">&amp;&amp;</span> <span class="token punctuation">(</span><span class="token variable">$countryIds</span> <span class="token operator">=</span> <span class="token variable">$scopes</span><span class="token operator">-&gt;</span><span class="token property">country</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;country_id&#39;</span><span class="token punctuation">,</span> <span class="token variable">$countryIds</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,17))])}const v=l(i,[["render",u]]);export{f as __pageData,v as default};
